import{_ as s,m as a,n as o,q as n}from"./chunks/framework.DMDh-7Lg.js";const h=JSON.parse('{"title":"Configuration Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),l={name:"reference/config.md"};function t(p,e,i,c,r,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Klix has two main configuration layers:</p><ul><li>app configuration through <code>App</code> and <code>AppConfig</code></li><li>process arguments through <code>CLIArgsParser</code></li></ul><p>This page documents both.</p><h2 id="app-configuration" tabindex="-1">App Configuration <a class="header-anchor" href="#app-configuration" aria-label="Permalink to &quot;App Configuration&quot;">​</a></h2><p>When you create an app:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">OpsTool</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    version</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">1.0.0</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Operations helper</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    state_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">OpsState</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    persist_session</span><span style="color:#89DDFF;">=True,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    theme</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">ThemeConfig</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">...</span><span style="color:#89DDFF;">),</span></span>\n<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><p>You are effectively populating <code>AppConfig</code>.</p><p>Current high-level fields:</p><ul><li><code>name</code></li><li><code>version</code></li><li><code>description</code></li><li><code>theme</code></li><li><code>config</code></li><li><code>persist_session</code></li><li><code>session_id</code></li><li><code>state_schema</code></li></ul><h2 id="name" tabindex="-1"><code>name</code> <a class="header-anchor" href="#name" aria-label="Permalink to &quot;`name`&quot;">​</a></h2><p>Used for:</p><ul><li>CLI program identity</li><li>help output</li><li>persistence directory naming</li><li>terminal metadata</li></ul><p>Choose something stable. Renaming the app changes where persisted sessions are stored.</p><h2 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;`version`&quot;">​</a></h2><p>Used by:</p><ul><li><code>--version</code> process argument</li><li>startup displays if your app shows it</li><li>metadata</li></ul><h2 id="description" tabindex="-1"><code>description</code> <a class="header-anchor" href="#description" aria-label="Permalink to &quot;`description`&quot;">​</a></h2><p>Used by:</p><ul><li>argument parser description</li><li>your own help and documentation</li></ul><h2 id="state-schema" tabindex="-1"><code>state_schema</code> <a class="header-anchor" href="#state-schema" aria-label="Permalink to &quot;`state_schema`&quot;">​</a></h2><p>Dataclass type used to construct <code>session.state</code>.</p><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">dataclass</span></span>\n<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> AppState</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">SessionState</span><span style="color:#89DDFF;">):</span></span>\n<span class="line"><span style="color:#BABED8;">    current_profile</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">default</span><span style="color:#89DDFF;">&quot;</span></span></code></pre></div><h2 id="persist-session" tabindex="-1"><code>persist_session</code> <a class="header-anchor" href="#persist-session" aria-label="Permalink to &quot;`persist_session`&quot;">​</a></h2><p>Boolean toggle for session state persistence.</p><p>When enabled:</p><ul><li>the app constructs a <code>SessionStateManager</code></li><li>state is saved on exit</li></ul><p>See <a href="./../guides/persistence">Persistence</a>.</p><h2 id="session-id" tabindex="-1"><code>session_id</code> <a class="header-anchor" href="#session-id" aria-label="Permalink to &quot;`session_id`&quot;">​</a></h2><p>Optional identifier used to load a persisted session file through the state manager.</p><p>If you want deterministic resumes, you need to provide or manage this value in your own app flow.</p><h2 id="theme" tabindex="-1"><code>theme</code> <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;`theme`&quot;">​</a></h2><p><code>ThemeConfig</code> instance controlling semantic colors.</p><p>See <a href="./../guides/theming">Theming</a>.</p><p>Useful recent additions:</p><ul><li><code>input_background</code></li><li><code>input_text_color</code></li></ul><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">theme</span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">ThemeConfig</span><span style="color:#89DDFF;">(</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    accent</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">#4F8CFF</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    input_background</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">#171B24</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    input_text_color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">#F5F7FA</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="config" tabindex="-1"><code>config</code> <a class="header-anchor" href="#config" aria-label="Permalink to &quot;`config`&quot;">​</a></h2><p><code>AppConfig</code> controls runtime prompt behavior that is not part of the semantic theme.</p><p>Current fields:</p><ul><li><code>history_path</code></li><li><code>log_path</code></li><li><code>clear_input_on_submit</code></li><li><code>max_history_size</code></li></ul><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">config</span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">AppConfig</span><span style="color:#89DDFF;">(</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    clear_input_on_submit</span><span style="color:#89DDFF;">=True,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    max_history_size</span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;">100</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><p><code>clear_input_on_submit</code> is opt-in and clears the visible prompt line after submit without affecting command execution.</p><p><code>max_history_size</code> limits per-session command history used by Up/Down navigation.</p><h2 id="cli-process-arguments" tabindex="-1">CLI Process Arguments <a class="header-anchor" href="#cli-process-arguments" aria-label="Permalink to &quot;CLI Process Arguments&quot;">​</a></h2><p>Klix wraps <code>argparse</code> in <code>CLIArgsParser</code>.</p><p>Built-in arguments:</p><ul><li><code>-v</code>, <code>--version</code></li><li><code>--config</code></li><li><code>--debug</code></li></ul><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">args </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> app</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">_cli_args</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">parse_args</span><span style="color:#89DDFF;">()</span></span></code></pre></div><p>The default <code>App</code> setup already creates this parser for you.</p><h2 id="about-help" tabindex="-1">About <code>--help</code> <a class="header-anchor" href="#about-help" aria-label="Permalink to &quot;About `--help`&quot;">​</a></h2><p>The parser is currently created with <code>add_help=False</code>.</p><p>That means:</p><ul><li><code>argparse</code> does not inject a default <code>--help</code></li><li>command help is expected to be handled at the app level, usually with a <code>/help</code> command</li></ul><p>This is an intentional design choice in the current codebase, but it can surprise users who expect standard process-level help behavior.</p><h2 id="adding-custom-process-arguments" tabindex="-1">Adding Custom Process Arguments <a class="header-anchor" href="#adding-custom-process-arguments" aria-label="Permalink to &quot;Adding Custom Process Arguments&quot;">​</a></h2><p><code>CLIArgsParser</code> exposes passthrough methods:</p><ul><li><code>add_argument(...)</code></li><li><code>add_argument_group(...)</code></li></ul><p>This is useful when your app needs startup flags before the interactive loop begins.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Confusing process arguments with slash commands. <code>--debug</code> is for process startup; <code>/debug</code> would be a command if you register it.</li><li>Renaming the app after shipping persistence to users.</li><li>Assuming persistence and session resume are the same thing.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./../installation">Installation</a></li><li><a href="./api">Reference: API</a></li><li><a href="./../faq">FAQ</a></li></ul>',67)])])}const y=s(l,[["render",t]]);export{h as __pageData,y as default};
